sort_by = frappe.form_dict.get("sort_by", None)
price_range = frappe.form_dict.get("price_range", None)
stock = frappe.form_dict.get("stock", None)

res = frappe.call('hopkins.api.get_products', page=page_num, page_length=page_length, search=search, category=category, sort_by=sort_by, price_range=price_range, stock=stock)
